import{renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import{enzymeCases,temperatureData,phData,conditionResult,foodMatch,validSites,fatGeometry,fatOutcome}from './digestive-models.js?v=20261023-physicscomplete01';
const txt=(x,y,t,s=15)=>`<text x="${x}" y="${y}" fill="#f8f6f2" text-anchor="middle" font-size="${s}">${t}</text>`;
const svg=(label,body)=>`<svg class="shell-diagram" role="img" aria-label="${label}" viewBox="0 0 480 350">${body}</svg>`;
const opts=(pairs,value)=>'<option value="">Choose…</option>'+pairs.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('');
const limit='<p class="diagram-caption">Original illustrative comparisons, not measured biological rates or molecular structures. Other variables are held equal. Different enzymes have different optima.</p>';
export function showDigestive(kind='enzymes',w={}){
 if(kind==='enzymes'){const e=enzymeCases.find(e=>e.id===w.enzyme)||enzymeCases[0],match=foodMatch(e.id,w.food||e.food),reacted=!!w.tested&&match;renderDiagram(e.name,reacted?e.food+' → '+e.product:'Match the food to its enzyme',svg('Schematic '+e.name+' reaction',txt(240,50,e.name,24)+`<rect x="40" y="110" width="170" height="85" rx="20" fill="#91a5b3" fill-opacity=".45"/>`+txt(125,160,w.food||e.food,20)+txt(240,160,'→',26)+`<rect x="275" y="110" width="165" height="85" rx="20" fill="#ed8b78" fill-opacity=".4"/>`+txt(357,160,reacted?e.product:'?',15)+txt(240,250,reacted?'Enzyme remains available':match?'Predict, then test':'No matching model reaction',15)+txt(240,310,'Word-equation model · no chemical symbols',12))+limit,'DIGESTIVE ENZYMES');return;}
 if(kind==='temperature'||kind==='ph'){const ph=kind==='ph',data=ph?phData[w.enzyme||'pepsin']:temperatureData,x=w.x??(ph?2:20),rate=ph?data.find(d=>d[0]===Number(x))?.[1]||0:conditionResult(x,w.heated).rate;const X=v=>70+(v-(ph?2:10))/(ph?6:50)*340,Y=v=>265-v*20;renderDiagram(ph?'Different pH optima':'Temperature and enzyme activity',rate+' illustrative product units / min',svg(ph?'Illustrative pH response':'Illustrative temperature response',`<path d="M70 50V265H420" fill="none" stroke="#d4dfe7"/>`+txt(245,325,ph?'pH':'Temperature / °C')+txt(240,25,'Illustrative rate / units min⁻¹',13)+`<polyline points="${data.map(([a,b])=>X(a)+','+Y(w.heated?0:b)).join(' ')}" fill="none" stroke="#ed8b78" stroke-width="4"/>`+data.map(([a,b])=>`<circle cx="${X(a)}" cy="${Y(w.heated?0:b)}" r="${a===Number(x)?9:4}" fill="#f8f6f2"/>`+txt(X(a),287,String(a),12)).join('')+txt(35,269,'0',12)+txt(35,89,'9',12)+txt(245,60,w.heated?'Previously heated to60°C: denatured':'Equal enzyme and substrate amounts',12))+limit,'COMPARE ENZYME CONDITIONS');return;}
 const split=!!w.split,g=fatGeometry(split),r=fatOutcome(!!w.alkaline,split,!!w.lipase);renderCustomModel({name:'Fat droplets and lipase',formula:g.count+' droplets · same total fat volume',kicker:'EMULSIFICATION MODEL',atoms:[],bonds:[],radius:3,viewKey:'bile-fat',startPaused:true,note:'Cubes stand for fat droplets · area comparison',aria:`${g.count} model fat cubes, total volume ${g.volume}, surface area ${g.area}. ${r.products} illustrative product units.`,diagram:svg('Equal-volume fat comparison',Array.from({length:g.count},(_,i)=>`<rect x="${split?130+(i%4)*60:180}" y="${split?100+Math.floor(i/4)*65:100}" width="${split?40:120}" height="${split?40:120}" rx="8" fill="#ed8b78" stroke="#f8f6f2"/>`).join('')+txt(240,275,`Volume ${g.volume} · surface area ${g.area} model units`,14)+txt(240,310,`${r.products} illustrative product units`,14))+limit,build:(group,T)=>{for(let i=0;i<g.count;i++){let cube=new T.Mesh(new T.BoxGeometry(g.side*.75,g.side*.75,g.side*.75),new T.MeshStandardMaterial({color:0xed8b78,roughness:.28,metalness:.06}));cube.position.set(split?(i%2-.5)*1.2:0,split?(Math.floor(i/2)%2-.5)*1.2:0,split?(Math.floor(i/4)-.5)*1.2:0);group.add(cube);}}});
}
export function mountDigestive(l,p,root,{save,done,feedback}){
 const w=p.widget,$=s=>root.querySelector(s),mode=l.widget,total=mode==='enzyme-conditions'?4:3;w.task??=0;w.passed??=[];const task=w.task%total;
 const field=(id,label,pairs,value)=>`<label class="field-label" for="${id}">${label}</label><select id="${id}" class="lab-select">${opts(pairs,value)}</select>`;
 const tail='<button id="checkDigestive" class="secondary">Check reasoning</button><button id="nextDigestive" class="secondary">Next challenge →</button><p id="digestiveProgress">'+w.passed.length+' / '+total+' complete</p>';
 const bind=(id,key=id)=>{$('#'+id).onchange=e=>{w[key]=e.target.value;save();};};
 const pass=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;done();}save();$('#digestiveProgress').textContent=w.passed.length+' / '+total+' complete';};
 let draw,validate;
 if(mode==='digestive-enzymes'){
  const e=enzymeCases[task];w.sites??={};w.tests??={};w.selected??={};w.answers??={};w.sites[e.id]??=[];
  root.innerHTML=`<p><b>${task+1} / 3 · Map ${e.name.toLowerCase()}</b></p>`+field('food','Choose the food molecule',enzymeCases.map(c=>[c.food,c.food]),w.selected[e.id])+`<button id="testFood" class="secondary">Test reaction →</button><p id="reactionReadout" aria-live="polite"></p><p>Select every site where this enzyme is produced.</p><div class="model-actions">`+[['salivary','Salivary glands'],['stomach','Stomach'],['pancreas','Pancreas'],['intestine','Small intestine'],['liver','Liver']].map(([v,t])=>`<button class="secondary" data-site="${v}" aria-pressed="${w.sites[e.id].includes(v)}">${t}</button>`).join('')+'</div>'+field('product','Products of this reaction',enzymeCases.map(c=>[c.product,c.product]),w.answers[e.id])+tail;
  draw=()=>{showDigestive('enzymes',{enzyme:e.id,food:w.selected[e.id]||e.food,tested:w.tests[e.id]});$('#reactionReadout').textContent=w.tests[e.id]?(foodMatch(e.id,w.selected[e.id])?e.food+' → '+e.product:'No matching model reaction. Compare another food.'):'Predict the food before testing.';};
  $('#food').onchange=e2=>{w.selected[e.id]=e2.target.value;w.tests[e.id]=false;save();draw();};$('#testFood').onclick=()=>{if(!w.selected[e.id]){feedback('Choose a food molecule first.',true);return;}w.tests[e.id]=true;save();draw();};for(let b of root.querySelectorAll('[data-site]'))b.onclick=()=>{let v=b.dataset.site,s=w.sites[e.id];w.sites[e.id]=s.includes(v)?s.filter(x=>x!==v):[...s,v];b.setAttribute('aria-pressed',w.sites[e.id].includes(v));save();};$('#product').onchange=ev=>{w.answers[e.id]=ev.target.value;save();};
  validate=()=>w.tests[e.id]&&foodMatch(e.id,w.selected[e.id])&&validSites(e.id,w.sites[e.id])&&w.answers[e.id]===e.product;
 }else if(mode==='enzyme-conditions'){
  w.comparisons??={};w.comparisons[task]??=[];
  if(task<3){const ph=task===2,pairs=ph?[[2,'pH2'],[4,'pH4'],[6,'pH6'],[8,'pH8']]:temperatureData.map(([x])=>[x,x+'°C']);w.conditionX??=20;w.phX??=2;w.phEnzyme??='pepsin';root.innerHTML=`<p><b>${task+1} / 4 · ${['Compare temperatures','Heat, then cool','Compare pH optima'][task]}</b></p><p>Equal enzyme/substrate amounts and observation time. Values illustrate one supplied comparison, not a universal optimum.</p>`+(ph?field('phEnzyme','Enzyme to compare',[['pepsin','Stomach protease model'],['amylase','Amylase model']],w.phEnzyme):'')+field('conditionX',ph?'pH':'Temperature',pairs,ph?w.phX:w.conditionX)+(task===1?'<button id="newEnzyme" class="secondary">Fresh enzyme sample</button><button id="heatEnzyme" class="secondary">Heat sample to60°C</button>':'')+'<button id="testCondition" class="secondary">Measure equal interval →</button><p id="conditionReadout" aria-live="polite"></p><ul id="conditionHistory"></ul>'+field('conditionReason','Explain the comparison',task===0?[['collision','Faster motion: more successful collisions'],['always','Hotter always means faster'],['cold','Cold destroys every active site']]:task===1?[['shape','Changed active site remains after cooling'],['cool','Cooling always repairs a denatured enzyme'],['used','Enzyme was digested as food']]:[['different','Enzyme-specific pH optima'],['all','All enzymes work best at pH7'],['acid','All acid conditions destroy every enzyme']],w['conditionReason'+task])+tail;
   draw=()=>{showDigestive(ph?'ph':'temperature',{x:ph?w.phX:w.conditionX,enzyme:w.phEnzyme,heated:task===1&&w.heated});$('#conditionReadout').textContent=(w.lastCondition?.task===task?w.lastCondition.text:'No interval measured yet.')+(task===1?' Sample: '+(w.heated?'previously heated to60°C':'fresh'):'');$('#conditionHistory').innerHTML=w.comparisons[task].map(key=>{const parts=key.split(':'),value=Number(parts.at(-1)),enzyme=parts[0],rate=ph?phData[enzyme].find(d=>d[0]===value)[1]:conditionResult(value,parts[0]==='heated').rate;return '<li>'+key+' → '+rate+' units/min</li>';}).join('');};
   $('#conditionX').onchange=ev=>{w[ph?'phX':'conditionX']=Number(ev.target.value);save();draw();};if(ph)$('#phEnzyme').onchange=ev=>{w.phEnzyme=ev.target.value||'pepsin';save();draw();};if(task===1){$('#newEnzyme').onclick=()=>{w.heated=false;save();draw();};$('#heatEnzyme').onclick=()=>{w.heated=true;w.conditionX=60;$('#conditionX').value='60';save();draw();};}
   $('#testCondition').onclick=()=>{const x=ph?w.phX:w.conditionX;if(!x){feedback('Select a condition first.',true);return;}if(!ph&&x>=60)w.heated=true;const rate=ph?phData[w.phEnzyme].find(d=>d[0]===x)[1]:conditionResult(x,task===1&&w.heated).rate,key=ph?w.phEnzyme+':'+x:(task===1?(w.heated?'heated:':'fresh:'):'')+x;if(!w.comparisons[task].includes(key))w.comparisons[task].push(key);w.lastCondition={task,text:`${x}${ph?' pH':'°C'}: ${rate} illustrative product units / min.`};save();draw();};$('#conditionReason').onchange=ev=>{w['conditionReason'+task]=ev.target.value;save();};
   validate=()=>w['conditionReason'+task]===['collision','shape','different'][task]&&(task===0?['10','40','60'].every(x=>w.comparisons[0].includes(x)):task===1?['fresh:20','heated:20'].every(x=>w.comparisons[1].includes(x)):['pepsin:2','pepsin:6','amylase:2','amylase:6'].every(x=>w.comparisons[2].includes(x)));
  }else{root.innerHTML='<p><b>4 / 4 · Calculate reaction rate</b></p><p>Original data:12 product units form in3 minutes. A second test reaches the same endpoint in40 seconds.</p><label class="field-label" for="amountRate">Mean product rate / units min⁻¹</label><input class="lab-select" type="number" id="amountRate" value="'+(w.amountRate??'')+'"><label class="field-label" for="endpointRate">Relative rate1/time / s⁻¹</label><input class="lab-select" type="number" step="any" id="endpointRate" value="'+(w.endpointRate??'')+'">'+tail;for(let key of ['amountRate','endpointRate'])$('#'+key).oninput=ev=>{w[key]=ev.target.value;save();};draw=()=>showDigestive('temperature',{x:40});validate=()=>Math.abs(Number(w.amountRate)-4)<.001&&Math.abs(Number(w.endpointRate)-.025)<.00001;}
 }else{
  w.bileSeen??=[];w.bileValues??={};
  if(task===0){root.innerHTML='<p><b>1 / 3 · Follow bile</b></p>'+field('bileMade','Made in…',[['liver','Liver'],['gall','Gallbladder'],['pancreas','Pancreas']],w.bileMade)+field('bileStored','Stored in…',[['gall','Gallbladder'],['liver','Liver'],['stomach','Stomach']],w.bileStored)+field('bileDestination','Released into…',[['small','Small intestine'],['stomach','Stomach'],['blood','Bloodstream']],w.bileDestination)+tail;for(let k of ['bileMade','bileStored','bileDestination'])bind(k);validate=()=>w.bileMade==='liver'&&w.bileStored==='gall'&&w.bileDestination==='small';draw=()=>renderDiagram('Bile: liver → gallbladder → intestine','Made · stored · released',svg('Schematic bile route',txt(240,65,'Liver',24)+txt(240,110,'↓')+txt(240,165,'Gallbladder',24)+txt(240,210,'↓')+txt(240,265,'Small intestine',24))+limit,'BILE ROUTE');
  }else{root.innerHTML=`<p><b>${task+1} / 3 · ${task===1?'Change area, conserve fat':'Separate the two roles of bile'}</b></p>`+field('splitFat','Fat droplets',[['whole','One large droplet'],['split','Eight smaller droplets']],w.split?'split':'whole')+(task===2?field('alkaline','Conditions',[['acid','Acidic'],['alkaline','Alkaline']],w.alkaline?'alkaline':'acid')+field('lipase','Lipase',[['absent','Absent'],['present','Present']],w.lipase?'present':'absent'):'')+'<button id="testFat" class="secondary">Compare equal interval →</button><p id="fatReadout" aria-live="polite"></p><ul id="fatHistory"></ul>'+field('fatReason','Explain the change',task===1?[['area','Same volume, greater surface area'],['digest','Bile chemically digested the fat'],['new','More fat was created']]:[['both','Alkaline pH + area help lipase'],['bile','Bile is the fat-digesting enzyme'],['none','Lipase is unnecessary']],w['fatReason'+task])+tail;
   draw=()=>{showDigestive('bile',w);const g=fatGeometry(w.split),r=fatOutcome(w.alkaline,w.split,w.lipase);$('#fatReadout').textContent=`Volume ${g.volume}; exposed area ${g.area} model units. `+(task===2?`${r.products} illustrative product units in equal time.`:'Emulsification alone changes no fat molecules into products.');$('#fatHistory').innerHTML=w.bileSeen.filter(key=>task===1?!key.includes(':'):key.includes(':')).map(key=>{if(task===1)return '<li>'+key+' droplets: area '+fatGeometry(key==='split').area+'</li>';const [a,s,e]=key.split(':').map(x=>x==='true');return '<li>'+(a?'Alkaline':'Acidic')+' · '+(s?'split':'whole')+' · lipase '+(e?'present':'absent')+': '+fatOutcome(a,s,e).products+' units</li>';}).join('');};$('#splitFat').onchange=ev=>{w.split=ev.target.value==='split';save();draw();};if(task===2){$('#alkaline').onchange=ev=>{w.alkaline=ev.target.value==='alkaline';save();draw();};$('#lipase').onchange=ev=>{w.lipase=ev.target.value==='present';save();draw();};}$('#testFat').onclick=()=>{let key=task===1?(w.split?'split':'whole'):[!!w.alkaline,!!w.split,!!w.lipase].join(':');if(!w.bileSeen.includes(key))w.bileSeen.push(key);save();draw();};$('#fatReason').onchange=ev=>{w['fatReason'+task]=ev.target.value;save();};validate=()=>task===1?['whole','split'].every(k=>w.bileSeen.includes(k))&&w.fatReason1==='area':['false:false:true','true:false:true','true:true:true','true:true:false'].every(k=>w.bileSeen.includes(k))&&w.fatReason2==='both';
  }
 }
 $('#checkDigestive').onclick=()=>{if(!validate()){feedback(mode==='digestive-enzymes'?'Test the correct food/product and select every production site, with no extras. Revisit Discover for the enzyme map.':mode==='enzyme-conditions'?['Measure10,40 and60°C; relate the rise and fall to motion and active-site shape.','Compare fresh20°C with the same sample at20°C after heating to60°C. Cooling alone does not repair this model enzyme.','Compare both enzymes at pH2 and6; their optima differ.','Rate = amount ÷ time;1/time is a relative rate only for the same endpoint.'][task]:task===0?'Bile is made in the liver, stored in the gallbladder and released into the small intestine.':task===1?'Compare whole and split droplets. Emulsification changes exposed area, not the total fat amount or its molecules.':'Compare acidic/alkaline intact fat with lipase, alkaline split fat with lipase, then remove lipase. Separate enzyme action from bile’s two roles.',true);return;}pass();feedback('Evidence and explanation agree. Continue to the next challenge.');};$('#nextDigestive').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountDigestive(l,p,root,{save,done,feedback});};draw();
}
